class Solution:
    def maxStrength(self, nums: List[int]) -> int:
        # Sort the numbers to handle negative numbers and zeroes easily
        nums.sort()

        # Initialize the result to 1 (multiplicative identity)
        result = 1
        has_positive = False

        # Iterate through the sorted numbers
        for num in nums:
            if num > 0:
                # Include all positive numbers
                result *= num
                has_positive = True
            elif num < 0:
                # Include pairs of negative numbers
                if len(nums) % 2 == 1 and nums[-1] == num:
                    # If there's an odd number of negative numbers and we're at the last one, skip it
                    continue
                result *= num

        # If there are no positive numbers and an odd number of negative numbers, return the largest negative number
        if not has_positive and len(nums) % 2 == 1:
            return nums[-1]

        return result

class Solution:
    def minExtraChar(self, s: str, dictionary: List[str]) -> int:
        n = len(s)
        dp = [0] * (n + 1)

        # Convert dictionary to a set for O(1) lookups
        word_set = set(dictionary)

        for i in range(1, n + 1):
            dp[i] = dp[i - 1] + 1  # Assume the current character is extra
            for j in range(i):
                if s[j:i] in word_set:
                    dp[i] = min(dp[i], dp[j])

        return dp[n]

class Solution:
    def buyChoco(self, prices: List[int], money: int) -> int:
        # Sort the prices array to find the two smallest prices
        prices.sort()

        # Calculate the sum of the two smallest prices
        min_sum = prices[0] + prices[1]

        # Check if the sum is within the budget
        if min_sum <= money:
            # Return the remaining money after the purchase
            return money - min_sum
        else:
            # Return the initial amount of money since it's not possible to buy two chocolates without going into debt
            return money

