class Solution:
    def count(self, num1: str, num2: str, min_sum: int, max_sum: int) -> int:
        def count_up_to(num_str, min_sum, max_sum):
            @cache
            def dp(pos, tight, sum_digits):
                if pos == len(num_str):
                    return min_sum <= sum_digits <= max_sum

                limit = int(num_str[pos]) if tight else 9
                count = 0
                for digit in range(limit + 1):
                    new_tight = tight and digit == limit
                    new_sum = sum_digits + digit
                    if new_sum > max_sum:
                        break
                    count = (count + dp(pos + 1, new_tight, new_sum)) % MOD
                return count

            return dp(0, True, 0)

        return (count_up_to(num2, min_sum, max_sum) - count_up_to(str(int(num1) - 1), min_sum, max_sum) + MOD) % MOD

