class Solution:
    def colorTheArray(self, n: int, queries: List[List[int]]) -> List[int]:
        nums = [0] * n
        answer = []
        adjacent_count = 0

        for index, color in queries:
            if nums[index] != 0:
                # Check the left adjacent pair
                if index > 0 and nums[index] == nums[index - 1]:
                    adjacent_count -= 1
                # Check the right adjacent pair
                if index < n - 1 and nums[index] == nums[index + 1]:
                    adjacent_count -= 1

            nums[index] = color

            if index > 0 and nums[index] == nums[index - 1]:
                adjacent_count += 1
            if index < n - 1 and nums[index] == nums[index + 1]:
                adjacent_count += 1

            answer.append(adjacent_count)

        return answer

class Solution:
    def longestSemiRepetitiveSubstring(self, s: str) -> int:
        n = len(s)
        if n <= 1:
            return n

        max_length = 1
        start = 0
        consecutive_pairs = 0

        for end in range(1, n):
            if s[end] == s[end - 1]:
                consecutive_pairs += 1

            while consecutive_pairs > 1:
                if s[start] == s[start + 1]:
                    consecutive_pairs -= 1
                start += 1

            max_length = max(max_length, end - start + 1)

        return max_length

class Solution:
    def doesValidArrayExist(self, derived: List[int]) -> bool:
        n = len(derived)

        # For n = 1, derived must be [0]
        if n == 1:
            return derived[0] == 0

        # Try both possible starting values for original[0]
        for start in [0, 1]:
            original = [start]
            valid = True

            # Compute the rest of the original array
            for i in range(n - 1):
                next_value = original[-1] ^ derived[i]
                original.append(next_value)

            # Check if the last value matches the first value
            if original[-1] ^ original[0] != derived[-1]:
                valid = False

            if valid:
                return True

        return False

