            if stack and ((char == 'B' and stack[-1] == 'A') or (char == 'D' and stack[-1] == 'C')):
                stack.pop()
            else:
                stack.append(char)
        return len(stack)

class Solution:
    def punishmentNumber(self, n: int) -> int:
        def can_partition(num_str, target):
            if not num_str and target == 0:
                return True
            if not num_str or target < 0:
                return False

            for i in range(1, len(num_str) + 1):
                current = int(num_str[:i])
                if can_partition(num_str[i:], target - current):
                    return True
            return False

        punishment_sum = 0
        for i in range(1, n + 1):
            square = i * i
            if can_partition(str(square), i):
                punishment_sum += square

        return punishment_sum

