class Solution:
    def paintWalls(self, cost: List[int], time: List[int]) -> int:
        n = len(cost)
        dp = [[float('inf')] * (n + 1) for _ in range(n + 1)]
        dp[0][0] = 0

        for i in range(1, n + 1):
            for j in range(n + 1):
                dp[i][j] = dp[i - 1][j]
                if j >= time[i - 1]:
                    dp[i][j] = min(dp[i][j], dp[i - 1][j - time[i - 1]] + cost[i - 1])

        return min(dp[n][j] for j in range(n + 1))

