class Solution:
    def makeSmallestPalindrome(self, s: str) -> str:
        n = len(s)
        s_list = list(s)

        # Two-pointer approach
        left = 0
        right = n - 1

        while left < right:
            if s_list[left] != s_list[right]:
                # Choose the lexicographically smaller character
                if s_list[left] < s_list[right]:
                    s_list[right] = s_list[left]
                else:
                    s_list[left] = s_list[right]
            left += 1
            right -= 1

        return ''.join(s_list)

class Solution:
    def minimumCost(self, s: str) -> int:
        n = len(s)

        # Helper function to calculate cost to make all characters equal to target ('0' or '1')
        def cost_to_target(target):
            total_cost = 0
            left_inverted = False
            right_inverted = False

            for i in range(n // 2):
                if s[i] != target:
                    if not left_inverted:
                        total_cost += i + 1
                        left_inverted = True
                if s[n - 1 - i] != target:
                    if not right_inverted:
                        total_cost += n - (n - 1 - i)
                        right_inverted = True

            # If the middle character is different and both halves are inverted, we need one more operation
            if n % 2 == 1 and s[n // 2] != target and left_inverted and right_inverted:
                total_cost += min(n // 2 + 1, n - (n // 2))

            return total_cost

        # Calculate the minimum cost by considering both '0' and '1' as target characters
        return min(cost_to_target('0'), cost_to_target('1'))

class Solution:
    def removeTrailingZeros(self, num: str) -> str:
        # Traverse the string from the end to find the first non-zero digit
        i = len(num) - 1
        while i >= 0 and num[i] == '0':
            i -= 1

        # Slice the string up to this position to remove trailing zeros
        return num[:i + 1]

