class Solution:
    def smallestString(self, s: str) -> str:
        n = len(s)
        chars = list(s)

        # Find the first character that is not 'a'
        start = 0
        while start < n and chars[start] == 'a':
            start += 1

        # If all characters are 'a', change the last character to 'z'
        if start == n:
            chars[-1] = 'z'
            return ''.join(chars)

        # Transform characters from the first non-'a' character until a 'a' is encountered again
        for i in range(start, n):
            if chars[i] == 'a':
                break
            chars[i] = chr(ord(chars[i]) - 1)

        return ''.join(chars)

class Solution:
    def relocateMarbles(self, nums: List[int], moveFrom: List[int], moveTo: List[int]) -> List[int]:
        # Initialize a set with the initial positions of marbles
        occupied_positions = set(nums)

        # Process each move
        for from_pos, to_pos in zip(moveFrom, moveTo):
            # Remove all marbles from the 'from' position
            if from_pos in occupied_positions:
                occupied_positions.remove(from_pos)
            # Add all marbles to the 'to' position
            occupied_positions.add(to_pos)

        # Return the sorted list of occupied positions
        return sorted(occupied_positions)

class Solution:
    def makeTheIntegerZero(self, num1: int, num2: int) -> int:
        # If num1 is already zero, no operations are needed
        if num1 == 0:
            return 0

        # We need to find the minimum k such that:
        # 1. num1 - k * num2 >= 0
        # 2. The number of set bits in (num1 - k * num2) is less than or equal to k
        # 3. k <= (num1 - k * num2)

        # Start with k = 1 and increment until we find a valid k or exceed the constraints
        k = 1
        while True:
            target = num1 - k * num2
            if target < 0:
                break
            if k <= target and k <= target.bit_count():
                return k
            k += 1

        # If no valid k is found, return -1
        return -1

