class Solution:
    def findValueOfPartition(self, nums: List[int]) -> int:
        # Sort the array to find the closest pair of elements
        nums.sort()

        # Initialize the minimum partition value to a large number
        min_partition_value = float('inf')

        # Iterate through the sorted array and find the minimum difference between consecutive elements
        for i in range(len(nums) - 1):
            min_partition_value = min(min_partition_value, nums[i + 1] - nums[i])

        return min_partition_value

class Solution:
    def maximumNumberOfStringPairs(self, words: List[str]) -> int:
        word_set = set(words)
        pair_count = 0

        for word in words:
            if word in word_set:
                reversed_word = word[::-1]
                if reversed_word != word and reversed_word in word_set:
                    pair_count += 1
                    word_set.remove(word)
                    word_set.remove(reversed_word)

        return pair_count

class Solution:
    def specialPerm(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        n = len(nums)

        # dp[mask][i] will store the number of special permutations ending with nums[i]
        # where mask is a bitmask representing the set of used elements.
        dp = [[0] * n for _ in range(1 << n)]

        # Base case: each single element is a valid permutation by itself
        for i in range(n):
            dp[1 << i][i] = 1

        # Fill the DP table
        for mask in range(1, 1 << n):
            for i in range(n):
                if mask & (1 << i) == 0:
                    continue
                for j in range(n):
                    if mask & (1 << j) and (nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0):
                        dp[mask][i] = (dp[mask][i] + dp[mask ^ (1 << i)][j]) % MOD

        # Sum up all valid permutations of length n
        result = sum(dp[(1 << n) - 1]) % MOD
        return result

