class Solution:
    def minimizeConcatenatedLength(self, words: List[str]) -> int:
        n = len(words)
        if n == 1:
            return len(words[0])

        # Initialize DP table
        dp = [[0, 0] for _ in range(n)]
        dp[0][0] = len(words[0])
        dp[0][1] = len(words[0])

        for i in range(1, n):
            current_word = words[i]
            prev_word = words[i-1]

            # Calculate lengths with and without overlap
            len_with_overlap = len(current_word) - 1 if current_word[0] == prev_word[-1] else len(current_word)
            len_without_overlap = len(current_word)

            dp[i][0] = min(dp[i-1][0] + len_without_overlap, dp[i-1][1] + len_with_overlap)
            dp[i][1] = min(dp[i-1][0] + len_with_overlap, dp[i-1][1] + len_without_overlap)

        # The result is the minimum length of the last string
        return min(dp[n-1][0], dp[n-1][1])

class Solution:
    def maximumJumps(self, nums: List[int], target: int) -> int:
        n = len(nums)
        dp = [-1] * n
        dp[0] = 0

        for i in range(1, n):
            for j in range(i):
                if nums[j] - target <= nums[i] <= nums[j] + target:
                    if dp[j] != -1:
                        dp[i] = max(dp[i], dp[j] + 1)

        return dp[n-1]
